import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"]
    stg = inputs["stg_account"]

    accounts = {}
    for _, row in dim.iterrows():
        acc_id = row["account_id"]
        lst = accounts.setdefault(acc_id, [])
        end_val = row["eff_end_date"]
        lst.append({
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": end_val if pd.notna(end_val) else None,
            "is_current": int(row["is_current"]),
        })

    def plans_equal(p1, p2):
        n1 = pd.isna(p1)
        n2 = pd.isna(p2)
        if n1 and n2:
            return True
        if n1 != n2:
            return False
        return p1 == p2

    stg_sorted = stg.sort_values(["account_id", "update_date"], kind="mergesort")

    for _, s in stg_sorted.iterrows():
        acc_id = s["account_id"]
        plan = s["plan"]
        d = s["update_date"]

        versions = accounts.setdefault(acc_id, [])

        if not versions:
            versions.append({
                "plan": plan,
                "eff_start_date": d,
                "eff_end_date": None,
                "is_current": 1,
            })
            continue

        covering = None
        for v in versions:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= d and (end is None or d < end):
                covering = v
                break

        if covering is None:
            # d is earlier than the account's earliest version
            f = min(versions, key=lambda v: v["eff_start_date"])
            versions.append({
                "plan": plan,
                "eff_start_date": d,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            if plans_equal(covering["plan"], plan):
                pass
            elif d == covering["eff_start_date"]:
                covering["plan"] = plan
            else:
                versions.append({
                    "plan": plan,
                    "eff_start_date": d,
                    "eff_end_date": covering["eff_end_date"],
                    "is_current": covering["is_current"],
                })
                covering["eff_end_date"] = d
                covering["is_current"] = 0

    rows = []
    for acc_id, versions in accounts.items():
        for v in versions:
            rows.append({
                "account_id": acc_id,
                "plan": v["plan"],
                "eff_start_date": v["eff_start_date"],
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            })

    out = pd.DataFrame(
        rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out.empty:
        out = out.sort_values(["account_id", "eff_start_date"], kind="mergesort").reset_index(drop=True)

    out["account_id"] = out["account_id"].astype("int64")
    out["is_current"] = out["is_current"].astype("int64")
    out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
    out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])

    return {"dim_account_out": out}
